using System.Text.Json;
namespace CMCutLab;
internal static class RenderTests
{
 internal static async Task<int> Run(){string root=Path.Combine(AppContext.BaseDirectory,"render-tests");Directory.CreateDirectory(root);var checks=new List<string>();try{
 var pace=new PaceEstimate();pace.Observe(0,0);pace.Observe(.5,5);if(pace.Remaining(95)!=null)throw new Exception("ETA shown too soon");pace.Observe(2,20);if(Math.Abs(pace.Remaining(80)!.Value-8)>.001)throw new Exception("ETA wrong");pace.Observe(8,20);if(pace.Remaining(80)<=8)throw new Exception("ETA did not react to stall");pace.Observe(9,1);if(pace.Remaining(80)!=null)throw new Exception("Pace did not reset after counter regression");checks.Add("PASS FC-derived pace estimate: warmup, steady speed, stall, reset");
 string source=Path.Combine(AppContext.BaseDirectory,"test-output","sample.ts");var media=await Engine.Probe(source,CancellationToken.None);string output=Path.Combine(root,"completed.mp4");if(File.Exists(output))File.Delete(output);var job=new RenderJob(source,output,"CPU AV1 / 2 Mbps",3);await Engine.Export(source,output,media,[(0,3)],"libsvtav1",2,CancellationToken.None,_=>{},job);var done=job.Snapshot();if(done.Active||done.Phase!="完了"||done.Fraction!=1||done.Bytes<=0||done.Total!=3)throw new Exception("Render completion details wrong");checks.Add("PASS real encode updates job phase/progress/bytes and completes after file commit");
 string cancelled=Path.Combine(root,"cancelled.mp4");if(File.Exists(cancelled))File.Delete(cancelled);using var cts=new CancellationTokenSource();var cancelJob=new RenderJob(source,cancelled,"CPU AV1",media.Duration);var task=Engine.Export(source,cancelled,media,[(0,media.Duration)],"libsvtav1",2,cts.Token,_=>{},cancelJob);await Task.Delay(80);using var panel=new RenderPanel();panel.Attach(cancelJob);panel.CancelRequested+=cts.Cancel;panel.TestCancel();try{await task.ConfigureAwait(false);throw new Exception("Cancel ignored");}catch(OperationCanceledException){}if(cancelJob.Snapshot().Phase!="キャンセル済み"||File.Exists(cancelled)||Directory.EnumerateFiles(root,".cmcut-*").Any())throw new Exception("Cancel left state or partial file");checks.Add("PASS dedicated render cancel button cancels active FFmpeg; temporary output removed");
 File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{Passed=true,Checks=checks},new JsonSerializerOptions{WriteIndented=true}));return 0;
 }catch(Exception e){checks.Add(e.ToString());File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{Passed=false,Checks=checks},new JsonSerializerOptions{WriteIndented=true}));return 1;}}
}
